    case 0x205:
        offline_event_time_update(OFFLINE_GIMBAL_YAW);
        break;
    case 0x206:
        offline_event_time_update(OFFLINE_GIMBAL_PITCH);
        break;
    case 0x207:
        offline_event_time_update(OFFLINE_GIMBAL_TURN_MOTOR);
        break;
    }
}

