    struct shoot *p_shoot;
    struct gimbal *p_gimbal;
    p_shoot = get_shoot();
    p_gimbal = get_gimbal();

    shoot_enable(p_shoot);
    gimbal_yaw_enable(p_gimbal);
    gimbal_pitch_enable(p_gimbal);
