    /* The parameters are not used. */
    (void)argc;

    cli_cmd_init();

    while (1)
    {
        uint16_t used_len;
        used_len = shell_fifo.used_num;
        ret = fifo_s_gets(&shell_fifo, input_buf, used_len);
        if (ret > 0)
