struct motor_data
{
    uint16_t ecd;
    uint16_t last_ecd;

    int16_t speed_rpm;
    int16_t given_current;

    int32_t round_cnt;
    int32_t total_ecd;
    int32_t total_angle;

    int32_t ecd_raw_rate;

    uint32_t msg_cnt;
    uint16_t offset_ecd;
};

struct can_msg
{
    uint32_t id : 29;
    uint32_t ide : 1;
    uint32_t rtr : 1;
    uint32_t rsv : 1;
    uint32_t len : 8;
    uint32_t priv : 8;
    uint32_t hdr : 8;
    uint32_t reserved : 8;
    uint8_t data[8];
};

struct motor_device
{
    struct device parent;
    struct motor_data data;

    enum device_can can_periph;
    uint16_t can_id;
    uint16_t init_offset_f;

    int16_t current;

    void (*get_data)(motor_device_t, uint8_t *);
};

