    if ((pchMessage == 0) || (dwLength <= 2))
    {
        return;
    }

    ucCRC = get_crc8((uint8_t *)pchMessage, dwLength - 1, CRC8_INIT);

    pchMessage[dwLength - 1] = ucCRC;
}


